import json
import re
from datetime import date

_DAY_RE = re.compile(r'^\d{4}-\d{2}-\d{2}$')


def _parse_day(value):
    """Validate a row day as a real YYYY-MM-DD calendar date and return it."""
    if not isinstance(value, str) or not _DAY_RE.match(value):
        raise ValueError(f'invalid day: {value!r}')
    try:
        return date.fromisoformat(value)
    except ValueError:
        raise ValueError(f'invalid day: {value!r}') from None


def _parse_row(row):
    """Validate a single row and return (amount_cents, day)."""
    if not isinstance(row, dict):
        raise ValueError(f'invalid row: {row!r}')
    tenant = row.get('tenant')
    if not isinstance(tenant, str) or not tenant:
        raise ValueError(f'invalid tenant: {tenant!r}')
    amount_cents = row.get('amount_cents')
    if isinstance(amount_cents, bool) or not isinstance(amount_cents, int):
        raise ValueError(f'invalid amount_cents: {amount_cents!r}')
    return amount_cents, _parse_day(row.get('day'))


def summarize_rows(text: str):
    """Parse a JSON array of rows. Each row has a nonempty string tenant, an integer
    amount_cents (negative amounts are allowed; booleans are invalid), and a valid YYYY-
    MM-DD string day. Return row_count, total_cents, first_day, and last_day. Empty
    input gives zero totals and null dates. Ignore extra fields. Raise ValueError on
    malformed JSON or rows."""
    try:
        rows = json.loads(text)
    except ValueError:
        raise ValueError(f'malformed JSON: {text!r}') from None
    if not isinstance(rows, list):
        raise ValueError(f'expected a JSON array of rows, got {type(rows).__name__}')
    total_cents = 0
    days = []
    for row in rows:
        amount_cents, day = _parse_row(row)
        total_cents += amount_cents
        days.append(day)
    return {
        'row_count': len(rows),
        'total_cents': total_cents,
        'first_day': min(days).isoformat() if days else None,
        'last_day': max(days).isoformat() if days else None,
    }
